INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT '7d84b0f8-027a-5992-a752-27133aa897ea'::uuid,'2026-10-17.v1','ru','sha256:3f2648c2008ae7436ab04fa28ce329f66d44960b7f1ca486ea5fdb814a872b04','{"assessmentVersionId":"7d84b0f8-027a-5992-a752-27133aa897ea","definitionKey":"asrs-6","definitionVersion":"v1","instrumentLocale":"en","translationVersion":"nyu-patient-en-v1","scoringKey":"asrs-v1-6-classic","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:3f2648c2008ae7436ab04fa28ce329f66d44960b7f1ca486ea5fdb814a872b04"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:2ed283668aa359650ee5763f1ddef5fcbbdd5efba2f58b6c4c074c79b4ce14c3',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[0,1,2,3,4,5,6],"mode":"screening","signature":{"dimensionClass":"symptoms","direction":"lower-reported-symptom-burden","displayKind":"screening-count","key":"symptoms.asrs6.shaded_count","max":6,"min":0,"sourceConstruct":"ASRS-v1.1 shaded-response count","timeframe":"past-6-months","unit":"qualifying-responses"},"source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","variants":[{"template":{"actions":["Результат {{value}} (0–6), категория «Ниже скринингового порога»: сопоставьте его с повседневным самочувствием. Даже этот результат не исключает проблему; беспокоящие симптомы можно обсудить со специалистом.","Можно записать конкретные примеры трудностей с вниманием или активностью и их влияние на повседневную жизнь для обсуждения с квалифицированным медицинским специалистом."],"bands":[{"code":"below_screen","from":0,"includeFrom":true,"includeTo":true,"label":"Ниже скринингового порога","source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","to":3},{"code":"screen_signal","from":4,"includeFrom":true,"includeTo":true,"label":"На уровне или выше скринингового порога","source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","to":6}],"basis":"screening","code":"below_screen","construct":"Отмеченные ответы в заштрихованных клетках","continuous":false,"currentBand":{"code":"below_screen","from":0,"includeFrom":true,"includeTo":true,"label":"Ниже скринингового порога","source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","to":3},"displayKind":"screening-count","label":"Ниже скринингового порога","limitations":["Опубликованный диапазон относится к этому инструменту и не устанавливает диагноз, причину или вероятность заболевания.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Отмеченные ответы в заштрихованных клетках: {{value}} (0–6). Пояснение Holistic House: {{value}} из 6 ответов попали в заштрихованные клетки по классическому правилу ASRS-v1.1 за последние 6 месяцев. Результат 0–3 ниже скринингового порога, но не исключает СДВГ. Это не диагноз, не оценка тяжести и не вероятность заболевания. Независимо от результата обсудите беспокоящие вас симптомы с квалифицированным медицинским специалистом. Использован оригинальный английский опросник; русский язык отчёта не меняет язык вопросов. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"difficulty","recommendedReview":false,"reliableDirection":true,"source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","summary":"Результат ниже скринингового порога, но не исключает СДВГ. Это не диагноз или оценка тяжести. Беспокоящие симптомы можно обсудить с квалифицированным специалистом независимо от балла.","verified":true},"values":[0,1,2,3]},{"template":{"actions":["Результат {{value}} (0–6), категория «На уровне или выше скринингового порога»: обсудите симптомы и влияние на обычные дела с квалифицированным специалистом; опросник не определяет диагноз или лечение.","Можно записать конкретные примеры трудностей с вниманием или активностью и их влияние на повседневную жизнь для обсуждения с квалифицированным медицинским специалистом."],"bands":[{"code":"below_screen","from":0,"includeFrom":true,"includeTo":true,"label":"Ниже скринингового порога","source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","to":3},{"code":"screen_signal","from":4,"includeFrom":true,"includeTo":true,"label":"На уровне или выше скринингового порога","source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","to":6}],"basis":"screening","code":"screen_signal","construct":"Отмеченные ответы в заштрихованных клетках","continuous":false,"currentBand":{"code":"screen_signal","from":4,"includeFrom":true,"includeTo":true,"label":"На уровне или выше скринингового порога","source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","to":6},"displayKind":"screening-count","label":"На уровне или выше скринингового порога","limitations":["Опубликованный диапазон относится к этому инструменту и не устанавливает диагноз, причину или вероятность заболевания.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Отмеченные ответы в заштрихованных клетках: {{value}} (0–6). Пояснение Holistic House: {{value}} из 6 ответов попали в заштрихованные клетки по классическому правилу ASRS-v1.1 за последние 6 месяцев. Результат 4–6 означает, что симптомы могут соответствовать СДВГ у взрослых. Возможно, будет полезно обсудить оценку с квалифицированным медицинским специалистом. Это не диагноз, не оценка тяжести и не вероятность заболевания. Независимо от результата обсудите беспокоящие вас симптомы с квалифицированным медицинским специалистом. Использован оригинальный английский опросник; русский язык отчёта не меняет язык вопросов. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"difficulty","recommendedReview":true,"reliableDirection":true,"source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","summary":"Результат на уровне или выше скринингового порога: симптомы могут соответствовать СДВГ у взрослых. Это не диагноз или оценка тяжести. Беспокоящие симптомы можно обсудить с квалифицированным специалистом независимо от балла.","verified":true},"values":[4,5,6]}]}],"discoveryClassification":{"basis":"discovery-only-not-clinical-validation","kind":"professional","policySource":"lib/assessments/test-kinds.js","policySourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","policySourceSha256":"sha256:77c573884f78cdc8c4fb58b15990dcce50218c4b6666a89c1ffe2fe8a4142167"},"interpretationVersion":"2026-10-17.v1","provenance":{"assessmentVersionId":"7d84b0f8-027a-5992-a752-27133aa897ea","contentHash":"sha256:3f2648c2008ae7436ab04fa28ce329f66d44960b7f1ca486ea5fdb814a872b04","definitionKey":"asrs-6","definitionVersion":"v1","instrumentLocale":"en","resultVersion":"v1","scoringKey":"asrs-v1-6-classic","scoringVersion":"v1","translationVersion":"nyu-patient-en-v1"},"rendererStrategy":"finite-domain-template.v1","reportLocale":"ru","rulesEngineVersion":"2026-10-16.v10","schemaVersion":"hh-interpretation.v1","source":{"citation":"Kessler RC et al. (2005). The World Health Organization Adult ADHD Self-Report Scale (ASRS): a short screening scale for use in the general population. Psychological Medicine 35(2):245–256. doi:10.1017/S0033291704002892.","formVersion":"ASRS-v1.1 6Q, patient-facing shaded form; not ASRS-5 or the full 18Q","languageNote":"Original English patient-facing ASRS-v1.1 6Q. Published validation is sample-specific and does not establish a diagnosis.","masterFilename":"6Q_ASRS_ENGLISH_final.pdf","masterSha256":"3383491ecbbd65beb79b97c86a49e72fac8a5fdf8c40d94bfe58ed9189bdfee4","minimumAge":18,"missingResponsePolicy":"Require all six valid answers. This is an HH implementation guardrail; no official prorating/imputation ru