INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT '132782f6-fe16-5d66-956c-ea47596f085a'::uuid,'2026-10-17.v1','ru','sha256:b64274437777684e0aea0150493adb4eb6015f9fd06bfbeb8b0b98998a67b387','{"assessmentVersionId":"132782f6-fe16-5d66-956c-ea47596f085a","definitionKey":"asrs-6","definitionVersion":"v1","instrumentLocale":"ru","translationVersion":"nyu-patient-ru-v1","scoringKey":"asrs-v1-6-classic","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:b64274437777684e0aea0150493adb4eb6015f9fd06bfbeb8b0b98998a67b387"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:4cb59d291be3732652f7e18876610c3eb310a16f2f57a51978771676f0a1491e',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[0,1,2,3,4,5,6],"mode":"screening","signature":{"dimensionClass":"symptoms","direction":"lower-reported-symptom-burden","displayKind":"screening-count","key":"symptoms.asrs6.shaded_count","max":6,"min":0,"sourceConstruct":"ASRS-v1.1 shaded-response count","timeframe":"past-6-months","unit":"qualifying-responses"},"source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","variants":[{"template":{"actions":["Результат {{value}} (0–6), категория «Ниже скринингового порога»: сопоставьте его с повседневным самочувствием. Даже этот результат не исключает проблему; беспокоящие симптомы можно обсудить со специалистом.","Можно записать конкретные примеры трудностей с вниманием или активностью и их влияние на повседневную жизнь для обсуждения с квалифицированным медицинским специалистом."],"bands":[{"code":"below_screen","from":0,"includeFrom":true,"includeTo":true,"label":"Ниже скринингового порога","source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","to":3},{"code":"screen_signal","from":4,"includeFrom":true,"includeTo":true,"label":"На уровне или выше скринингового порога","source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","to":6}],"basis":"screening","code":"below_screen","construct":"Отмеченные ответы в заштрихованных клетках","continuous":false,"currentBand":{"code":"below_screen","from":0,"includeFrom":true,"includeTo":true,"label":"Ниже скринингового порога","source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","to":3},"displayKind":"screening-count","label":"Ниже скринингового порога","limitations":["Опубликованный диапазон относится к этому инструменту и не устанавливает диагноз, причину или вероятность заболевания."],"meaning":"Отмеченные ответы в заштрихованных клетках: {{value}} (0–6). Пояснение Holistic House: {{value}} из 6 ответов попали в заштрихованные клетки по классическому правилу ASRS-v1.1 за последние 6 месяцев. Результат 0–3 ниже скринингового порога, но не исключает СДВГ. Это не диагноз, не оценка тяжести и не вероятность заболевания. Независимо от результата обсудите беспокоящие вас симптомы с квалифицированным медицинским специалистом. Использован официальный русский перевод, распространяемый NYU; валидация именно этой русской формулировки не подтверждена.","presentationDirection":"difficulty","recommendedReview":false,"reliableDirection":true,"source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","summary":"Результат ниже скринингового порога, но не исключает СДВГ. Это не диагноз или оценка тяжести. Беспокоящие симптомы можно обсудить с квалифицированным специалистом независимо от балла.","verified":true},"values":[0,1,2,3]},{"template":{"actions":["Результат {{value}} (0–6), категория «На уровне или выше скринингового порога»: обсудите симптомы и влияние на обычные дела с квалифицированным специалистом; опросник не определяет диагноз или лечение.","Можно записать конкретные примеры трудностей с вниманием или активностью и их влияние на повседневную жизнь для обсуждения с квалифицированным медицинским специалистом."],"bands":[{"code":"below_screen","from":0,"includeFrom":true,"includeTo":true,"label":"Ниже скринингового порога","source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","to":3},{"code":"screen_signal","from":4,"includeFrom":true,"includeTo":true,"label":"На уровне или выше скринингового порога","source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","to":6}],"basis":"screening","code":"screen_signal","construct":"Отмеченные ответы в заштрихованных клетках","continuous":false,"currentBand":{"code":"screen_signal","from":4,"includeFrom":true,"includeTo":true,"label":"На уровне или выше скринингового порога","source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","to":6},"displayKind":"screening-count","label":"На уровне или выше скринингового порога","limitations":["Опубликованный диапазон относится к этому инструменту и не устанавливает диагноз, причину или вероятность заболевания."],"meaning":"Отмеченные ответы в заштрихованных клетках: {{value}} (0–6). Пояснение Holistic House: {{value}} из 6 ответов попали в заштрихованные клетки по классическому правилу ASRS-v1.1 за последние 6 месяцев. Результат 4–6 означает, что симптомы могут соответствовать СДВГ у взрослых. Возможно, будет полезно обсудить оценку с квалифицированным медицинским специалистом. Это не диагноз, не оценка тяжести и не вероятность заболевания. Независимо от результата обсудите беспокоящие вас симптомы с квалифицированным медицинским специалистом. Использован официальный русский перевод, распространяемый NYU; валидация именно этой русской формулировки не подтверждена.","presentationDirection":"difficulty","recommendedReview":true,"reliableDirection":true,"source":"https://license.tov.med.nyu.edu/product/asrs6Qscreener","summary":"Результат на уровне или выше скринингового порога: симптомы могут соответствовать СДВГ у взрослых. Это не диагноз или оценка тяжести. Беспокоящие симптомы можно обсудить с квалифицированным специалистом независимо от балла.","verified":true},"values":[4,5,6]}]}],"discoveryClassification":{"basis":"discovery-only-not-clinical-validation","kind":"professional","policySource":"lib/assessments/test-kinds.js","policySourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","policySourceSha256":"sha256:77c573884f78cdc8c4fb58b15990dcce50218c4b6666a89c1ffe2fe8a4142167"},"interpretationVersion":"2026-10-17.v1","provenance":{"assessmentVersionId":"132782f6-fe16-5d66-956c-ea47596f085a","contentHash":"sha256:b64274437777684e0aea0150493adb4eb6015f9fd06bfbeb8b0b98998a67b387","definitionKey":"asrs-6","definitionVersion":"v1","instrumentLocale":"ru","resultVersion":"v1","scoringKey":"asrs-v1-6-classic","scoringVersion":"v1","translationVersion":"nyu-patient-ru-v1"},"rendererStrategy":"finite-domain-template.v1","reportLocale":"ru","rulesEngineVersion":"2026-10-16.v10","schemaVersion":"hh-interpretation.v1","source":{"citation":"Kessler RC et al. (2005). The World Health Organization Adult ADHD Self-Report Scale (ASRS): a short screening scale for use in the general population. Psychological Medicine 35(2):245–256. doi:10.1017/S0033291704002892.","formVersion":"ASRS-v1.1 6Q, patient-facing shaded form; not ASRS-5 or the full 18Q","languageNote":"Official Russian translation distributed by NYU. Exact-version Russian validation was not established. Do not attach the performance figures of the differently worded 2026 Russian validation.","masterFilename":"6Q_Russian_final.pdf","masterSha256":"43068fbc890d8f05ab08d563d9efd6464feafd130a9c881be73afc2f07651382","minimumAge":18,"missingResponsePolicy":"Require all six valid answers. This is an HH implementation guardrail; no official prorating/imputation rule was located. Never convert missing to zero.","nonDiagnostic":true,"permission":"NYU permits clinical, nonclinical and commercial use with attribution. Electronic reproduction is permitted; no other modifications are permitted. Not public domain.","permissionUrl":"https://license.tov.med.nyu.edu/product/asrs