INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT 'b3cb9fb1-0626-52c6-a678-fc71b1ae34b3'::uuid,'2026-10-17.v1','ru','sha256:86b3c6a2fc11462c66620b6835de10fc8beac4f568d756c7783b0fcdb6609181','{"assessmentVersionId":"b3cb9fb1-0626-52c6-a678-fc71b1ae34b3","definitionKey":"erq","definitionVersion":"v1","instrumentLocale":"en","translationVersion":"official-en-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:86b3c6a2fc11462c66620b6835de10fc8beac4f568d756c7783b0fcdb6609181"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:62ea4113439d6f3a39d6872d8b7607f8a0e25b2b279393a1bd113e87bbe4beba',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[1,1.17,1.33,1.5,1.67,1.83,2,2.17,2.33,2.5,2.67,2.83,3,3.17,3.33,3.5,3.67,3.83,4,4.17,4.33,4.5,4.67,4.83,5,5.17,5.33,5.5,5.67,5.83,6,6.17,6.33,6.5,6.67,6.83,7],"mode":"descriptive","signature":{"dimensionClass":"resources","direction":"non-normative","key":"resources.erq.reappraisal","max":7,"min":1,"sourceConstruct":"Cognitive reappraisal","timeframe":"general","unit":"points"},"source":"https://www.cmu.edu/common-cold-project/measures-by-study/psychological-and-social-constructs/other-psychological-measures/emotion-regulation.html","variants":[{"template":{"actions":["Для результата {{value}} (1–7) по теме «Когнитивная переоценка» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","Отмечайте, помогает ли переосмысление события увидеть выбор, не отрицая чувства."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Когнитивная переоценка","continuous":true,"currentBand":null,"label":"Описательный результат (1–7)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Когнитивная переоценка: {{value}} (1–7). Среднее отражает привычку менять взгляд на ситуацию для изменения эмоционального переживания. Более высокий балл означает большее согласие с этой стратегией; её полезность зависит от ситуации. Среднее 6 ответов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://www.cmu.edu/common-cold-project/measures-by-study/psychological-and-social-constructs/other-psychological-measures/emotion-regulation.html","summary":"Среднее отражает привычку менять взгляд на ситуацию для изменения эмоционального переживания. Более высокий балл означает большее согласие с этой стратегией; её полезность зависит от ситуации.","verified":true},"values":[1,1.17,1.33,1.5,1.67,1.83,2,2.17,2.33,2.5,2.67,2.83,3,3.17,3.33,3.5,3.67,3.83,4,4.17,4.33,4.5,4.67,4.83,5,5.17,5.33,5.5,5.67,5.83,6,6.17,6.33,6.5,6.67,6.83,7]}]},{"allowedValues":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5,5.25,5.5,5.75,6,6.25,6.5,6.75,7],"mode":"descriptive","signature":{"dimensionClass":"resources","direction":"non-normative","key":"resources.erq.suppression","max":7,"min":1,"sourceConstruct":"Expressive suppression","timeframe":"general","unit":"points"},"source":"https://www.cmu.edu/common-cold-project/measures-by-study/psychological-and-social-constructs/other-psychological-measures/emotion-regulation.html","variants":[{"template":{"actions":["Для результата {{value}} (1–7) по теме «Подавление выражения эмоций» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","Подумайте, когда сдерживать внешнее выражение чувств полезно, а когда безопаснее ими поделиться."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Подавление выражения эмоций","continuous":true,"currentBand":null,"label":"Описательный результат (1–7)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Подавление выражения эмоций: {{value}} (1–7). Среднее отражает привычку ограничивать внешнее выражение эмоций. Более высокий балл означает большее согласие с этой стратегией, а не отсутствие эмоций; её полезность зависит от ситуации. Среднее 4 ответов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://www.cmu.edu/common-cold-project/measures-by-study/psychological-and-social-constructs/other-psychological-measures/emotion-regulation.html","summary":"Среднее отражает привычку ограничивать внешнее выражение эмоций. Более высокий балл означает большее согласие с этой стратегией, а не отсутствие эмоций; её полезность зависит от ситуации.","verified":true},"values":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5,5.25,5.5,5.75,6,6.25,6.5,6.75,7]}]}],"discoveryClassification":{"basis":"discovery-only-not-clinical-validation","kind":"professional","policySource":"lib/assessments/test-kinds.js","policySourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","policySourceSha256":"sha256:77c573884f78cdc8c4fb58b15990dcce50218c4b6666a89c1ffe2fe8a4142167"},"interpretationVersion":"2026-10-17.v1","provenance":{"assessmentVersionId":"b3cb9fb1-0626-52c