INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT '9d5ee46e-35c7-5585-8db0-942db578cf44'::uuid,'2026-10-17.v1','ru','sha256:5f6c12d5e6198e9bcd1488af62a0bb432674843ade9dd502378da982205ea066','{"assessmentVersionId":"9d5ee46e-35c7-5585-8db0-942db578cf44","definitionKey":"hh-body-signals","definitionVersion":"v1","instrumentLocale":"ru","translationVersion":"hh-ru-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:5f6c12d5e6198e9bcd1488af62a0bb432674843ade9dd502378da982205ea066"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:cd5a0abec9dc1361b4f0603957e0710646a2e7d7f9f70f478d59005c844a50e2',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[0,0.17,0.33,0.5,0.67,0.83,1,1.17,1.33,1.5,1.67,1.83,2,2.17,2.33,2.5,2.67,2.83,3,3.17,3.33,3.5,3.67,3.83,4],"mode":"descriptive","signature":{"dimensionClass":"state","direction":"higher-reported-resource","key":"state.body_signals.overall","max":4,"min":0,"sourceConstruct":"Сигналы тела","timeframe":"right-now","unit":"points"},"source":null,"variants":[{"template":{"actions":["Результат {{value}} (0–4) по теме «Распознавание телесных потребностей и отклик на них» на нижней границе возможных ответов. Проверьте, соответствует ли это вашему опыту, и отметьте исключения, которые общий балл не показывает.","Опишите телесный сигнал без вывода о причине и отметьте, когда нужен медицинский совет."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Распознавание телесных потребностей и отклик на них","continuous":true,"currentBand":null,"label":"Описательный результат (0–4)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Это авторский опросник Holistic House для самонаблюдения. Его результат нельзя считать валидированной клинической оценкой или доказательством эффективности помощи."],"meaning":"Распознавание телесных потребностей и отклик на них: {{value}} (0–4). Больший балл отражает большее согласие с утверждениями о теме «Распознавание телесных потребностей и отклик на них». Это описание доступного опыта, а не оценка ваших качеств; общий показатель может скрывать различия между ответами. Среднее 6 ответов. Проверенные клинические категории для этого результата здесь не присваиваются. Это авторский опросник Holistic House для самонаблюдения. Его результат нельзя считать валидированной клинической оценкой или доказательством эффективности помощи.","presentationDirection":"resource","recommendedReview":false,"reliableDirection":true,"source":null,"summary":"Больший балл отражает большее согласие с утверждениями о теме «Распознавание телесных потребностей и отклик на них». Это описание доступного опыта, а не оценка ваших качеств; общий показатель может скрывать различия между ответами.","verified":true},"values":[0]},{"template":{"actions":["Используйте {{value}} (0–4) по теме «Распознавание телесных потребностей и отклик на них» как исходное наблюдение: опишите конкретную ситуацию и её влияние на день. Сравнивайте только ту же версию, язык вопросов и период измерения.","Опишите телесный сигнал без вывода о причине и отметьте, когда нужен медицинский совет."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Распознавание телесных потребностей и отклик на них","continuous":true,"currentBand":null,"label":"Описательный результат (0–4)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Это авторский опросник Holistic House для самонаблюдения. Его результат нельзя считать валидированной клинической оценкой или доказательством эффективности помощи."],"meaning":"Распознавание теле