INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT 'd4cda843-f234-5304-aca0-17dfa59e4c3c'::uuid,'2026-10-17.v1','ru','sha256:7991d7d69831c2e8e06724090c463d921f001ac5b2939772501c113972debcec','{"assessmentVersionId":"d4cda843-f234-5304-aca0-17dfa59e4c3c","definitionKey":"hh-money-pressure","definitionVersion":"v1","instrumentLocale":"en","translationVersion":"hh-en-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:7991d7d69831c2e8e06724090c463d921f001ac5b2939772501c113972debcec"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:f0ceed736b0b338af2d5e69606598cabb9eb201ed306c7e5aa86fdca050472ca',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":false,"dimensions":[{"allowedValues":[0,0.17,0.33,0.5,0.67,0.83,1,1.17,1.33,1.5,1.67,1.83,2,2.17,2.33,2.5,2.67,2.83,3,3.17,3.33,3.5,3.67,3.83,4],"mode":"descriptive","signature":{"dimensionClass":"state","direction":"lower-reported-difficulty","key":"state.money_pressure.overall","max":4,"min":0,"sourceConstruct":"Money Pressure","timeframe":"past-7-days","unit":"points"},"source":null,"variants":[{"template":{"actions":["При результате {{value}} (0–4) отдельно отметьте трудность и способ совладания по теме «Беспокойство о деньгах и доступное совладание»: один общий балл их не различает.","Разделите финансовые задачи, на которые можно влиять, и беспокойство вне непосредственного контроля."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Беспокойство о деньгах и доступное совладание","continuous":true,"currentBand":null,"label":"Описательный результат (0–4)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Это авторский опросник Holistic House для самонаблюдения. Его результат нельзя считать валидированной клинической оценкой или доказательством эффективности помощи.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","В этой неизменённой версии среднее объединяет утверждения о трудности и о совладании без разворота ответов. Его нельзя читать как чистую тяжесть проблемы; рассматривайте оба вида опыта отдельно."],"meaning":"Беспокойство о деньгах и доступное совладание: {{value}} (0–4). Это среднее ответов о трудностях и способах совладания; оно не позволяет отделить нагрузку от поддержки. Среднее 6 ответов. Проверенные клинические категории для этого результата здесь не присваиваются. Это авторский опросник Holistic House для самонаблюдения. Его результат нельзя считать валидированной клинической оценкой или доказательством эффективности помощи. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника. В этой неизменённой версии среднее объединяет утверждения о трудности и о совладании без разворота ответов. Его нельзя читать как чистую тяжесть проблемы; рассматривайте оба вида опыта отдельно.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":false,"source":null,"summary":"Это среднее ответов о трудностях и способах совладания; оно не позволяет отделить нагрузку от поддержки.","verified":true},"values":[0,0.17,0.33,0.5,0.67,0.83,1,1.17,1.33,1.5,1.67,1.83,2,2.17,2.33,2.5,2.67,2.83,3,3.17,3.33,3.5,3.67,3.83,4]}]}],"discoveryClassification":{"basis":"discovery-only-not-clinical-validation","kind":"monitoring","policySource":"lib/assessments/test-kinds.js","policySourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","policySourceSha256":"sha256:77c573884f78cdc8c4fb58b15990dcce50218c4b6666a89c1ffe2fe8a4142167"},"interpretationVersion":"2026-10-17.v1","provenance":{"assessmentVersionId":"d4cda843-f234-5304-aca0-17dfa59e4c3c","contentHash":"sha256:7991d7d69831c2e8e0672409