INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT '8cbbaa9b-7920-5e76-a8ca-62767f8114e4'::uuid,'2026-10-17.v1','ru','sha256:1ff3b8aaa14ed1afc05dc47d0b22534ce445da1b3a3d91dfdcce186f665f5bf5','{"assessmentVersionId":"8cbbaa9b-7920-5e76-a8ca-62767f8114e4","definitionKey":"hh-perfectionism-pressure","definitionVersion":"v1","instrumentLocale":"ru","translationVersion":"hh-ru-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:1ff3b8aaa14ed1afc05dc47d0b22534ce445da1b3a3d91dfdcce186f665f5bf5"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:a47ebbb82710fab5b53ddc8cb79d17be003c5058eeb71fb45a1c8da2a381c978',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[0,0.17,0.33,0.5,0.67,0.83,1,1.17,1.33,1.5,1.67,1.83,2,2.17,2.33,2.5,2.67,2.83,3,3.17,3.33,3.5,3.67,3.83,4],"mode":"descriptive","signature":{"dimensionClass":"function","direction":"higher-reported-resource","key":"function.perfectionism_pressure.overall","max":4,"min":0,"sourceConstruct":"Достаточно хорошо","timeframe":"past-7-days","unit":"points"},"source":null,"variants":[{"template":{"actions":["Результат {{value}} (0–4) по теме «Гибкость стандартов и разрешение завершать дела» на нижней границе возможных ответов. Проверьте, соответствует ли это вашему опыту, и отметьте исключения, которые общий балл не показывает.","Определите «достаточно хорошо» для одной задачи и отметьте, как это влияет на затраты сил."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Гибкость стандартов и разрешение завершать дела","continuous":true,"currentBand":null,"label":"Описательный результат (0–4)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Это авторский опросник Holistic House для самонаблюдения. Его результат нельзя считать валидированной клинической оценкой или доказательством эффективности помощи."],"meaning":"Гибкость стандартов и разрешение завершать дела: {{value}} (0–4). Больший балл отражает большее согласие с утверждениями о теме «Гибкость стандартов и разрешение завершать дела». Это описание доступного опыта, а не оценка ваших качеств; общий показатель может скрывать различия между ответами. Среднее 6 ответов. Проверенные клинические категории для этого результата здесь не присваиваются. Это авторский опросник Holistic House для самонаблюдения. Его результат нельзя считать валидированной клинической оценкой или доказательством эффективности помощи.","presentationDirection":"resource","recommendedReview":false,"reliableDirection":true,"source":null,"summary":"Больший балл отражает большее согласие с утверждениями о теме «Гибкость стандартов и разрешение завершать дела». Это описание доступного опыта, а не оценка ваших качеств; общий показатель может скрывать различия между ответами.","verified":true},"values":[0]},{"template":{"actions":["Используйте {{value}} (0–4) по теме «Гибкость стандартов и разрешение завершать дела» как исходное наблюдение: опишите конкретную ситуацию и её влияние на день. Сравнивайте только ту же версию, язык вопросов и период измерения.","Определите «достаточно хорошо» для одной задачи и отметьте, как это влияет на затраты сил."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Гибкость стандартов и разрешение завершать дела","continuous":true,"currentBand":null,"label":"Описательный результат (0–4)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Это авторский опросник Holistic House для самонаблюдения. Его результат нельзя считать валидированной клинической оценкой или доказательством эффективности помощи."],"meaning":"Гибкост