INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT 'd6277cc3-f343-5576-afc4-2a4717387448'::uuid,'2026-10-17.v1','ru','sha256:ae14c686ba6291bbe82550dfc4d2936ac7897d389439b9a5c654bb7f9d097154','{"assessmentVersionId":"d6277cc3-f343-5576-afc4-2a4717387448","definitionKey":"ipip-aspect-volatility-10","definitionVersion":"v1","instrumentLocale":"en","translationVersion":"original-en-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:ae14c686ba6291bbe82550dfc4d2936ac7897d389439b9a5c654bb7f9d097154"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:d8ea4b900c71a2c9eb99edd9634b2d4c3e5a182442f2e5311810ac89ef59fd3e',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[1,1.1,1.2,1.3,1.4,1.5,1.6,1.7,1.8,1.9,2,2.1,2.2,2.3,2.4,2.5,2.6,2.7,2.8,2.9,3,3.1,3.2,3.3,3.4,3.5,3.6,3.7,3.8,3.9,4,4.1,4.2,4.3,4.4,4.5,4.6,4.7,4.8,4.9,5],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.bfas.volatility","max":5,"min":1,"sourceConstruct":"Emotional volatility","timeframe":"general-self-description","unit":"points"},"source":"https://ipip.ori.org/BFASKeys.htm","variants":[{"template":{"actions":["Для результата {{value}} (1–5) по теме «Эмоциональная реактивность» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Когда раздражение нарастает, попробуйте ненадолго отложить ответ и заметить, что его вызвало."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Эмоциональная реактивность","continuous":true,"currentBand":null,"label":"Описательный результат (1–5)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Эмоциональная реактивность: {{value}} (1–5). Больший балл описывает более лёгкое возникновение раздражения, огорчения и сильного эмоционального отклика; меньший — более устойчивое спокойствие. Эта грань касается реактивности эмоций, а не их обоснованности или опасности человека. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 10 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://ipip.ori.org/BFASKeys.htm","summary":"Больший балл описывает более лёгкое возникновение раздражения, огорчения и сильного эмоционального отклика; меньший — более устойчивое спокойствие. Эта грань касается реактивности эмоций, а не их обоснованности или опасности человека. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.1,1.2,1.3,1.4,1.5,1.6,1.7,1.8,1.9,2,2.1,2.2,2.3,2.4,2.5,2.6,2.7,2.8,2.9,3,3.1,3.2,3.3,3.4,3.5,3.6,3.7,3.8,3.9,4,4.1,4.2,4.3,4.4,4.5,4.6,4.7,4.8,4.9,5]}]}],"discoveryClassification":{"basis":"discovery-only-not-clinical-validation","kind":"professional","policySource":"lib/assessments/test-kinds.js","policySourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","policySourceSha256":"sha256:77c573884f78cdc8c4fb58b15990dcce50218c4b6666a89c1ffe2fe8a4142167"},"interpretationVersion":"2026-1