INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT '918240af-eb81-514b-ad1f-a7d9d6f60bff'::uuid,'2026-10-17.v1','ru','sha256:93f411874648fb1734db5bf18b0721a8341067635284f22c34f9c160a7b18e55','{"assessmentVersionId":"918240af-eb81-514b-ad1f-a7d9d6f60bff","definitionKey":"ipip-aspect-orderliness-10","definitionVersion":"v1","instrumentLocale":"en","translationVersion":"original-en-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:93f411874648fb1734db5bf18b0721a8341067635284f22c34f9c160a7b18e55"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:85da7c1a37389ca26746b09b37efbd302866061c3546d301f4c47120ab74daf8',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[1,1.1,1.2,1.3,1.4,1.5,1.6,1.7,1.8,1.9,2,2.1,2.2,2.3,2.4,2.5,2.6,2.7,2.8,2.9,3,3.1,3.2,3.3,3.4,3.5,3.6,3.7,3.8,3.9,4,4.1,4.2,4.3,4.4,4.5,4.6,4.7,4.8,4.9,5],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.bfas.orderliness","max":5,"min":1,"sourceConstruct":"Orderliness","timeframe":"general-self-description","unit":"points"},"source":"https://ipip.ori.org/BFASKeys.htm","variants":[{"template":{"actions":["Для результата {{value}} (1–5) по теме «Любовь к порядку» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Определите, где простой распорядок экономит силы, а где полезнее оставить место для изменений."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Любовь к порядку","continuous":true,"currentBand":null,"label":"Описательный результат (1–5)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Любовь к порядку: {{value}} (1–5). Больший балл описывает более сильное предпочтение порядка, расписаний, правил и внимания к деталям; меньший — большую терпимость к беспорядку и меньшую приверженность распорядку. Ни один конец не задаёт лучший способ организации всех ситуаций. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 10 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://ipip.ori.org/BFASKeys.htm","summary":"Больший балл описывает более сильное предпочтение порядка, расписаний, правил и внимания к деталям; меньший — большую терпимость к беспорядку и меньшую приверженность распорядку. Ни один конец не задаёт лучший способ организации всех ситуаций. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.1,1.2,1.3,1.4,1.5,1.6,1.7,1.8,1.9,2,2.1,2.2,2.3,2.4,2.5,2.6,2.7,2.8,2.9,3,3.1,3.2,3.3,3.4,3.5,3.6,3.7,3.8,3.9,4,4.1,4.2,4.3,4.4,4.5,4.6,4.7,4.8,4.9,5]}]}],"discoveryClassification":{"basis":"discovery-only-not-clinical-validation","kind":"professional","policySource":"lib/assessments/test-kinds.js","policySourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","policySourceSha256":"sha256:77c573884f78cdc8c4fb58b15990dcce50218c4b6666a89c1ffe2fe8a4142167"},"interpretationVersion":"2026-10-17.v1","provenan