INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT 'ac69dd83-0fa4-5ffd-ae46-f86e48edd369'::uuid,'2026-10-17.v1','ru','sha256:666d2327041564f4036e9f47475f4c15b904894de3db7ad7a5b20f21e965ace7','{"assessmentVersionId":"ac69dd83-0fa4-5ffd-ae46-f86e48edd369","definitionKey":"ipip-via-r-capacity-for-love-4","definitionVersion":"v1","instrumentLocale":"en","translationVersion":"original-en-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:666d2327041564f4036e9f47475f4c15b904894de3db7ad7a5b20f21e965ace7"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:ccdeda47a42d66beb81134aaa8af0f8a19830daffd2f902917f2a5c4447b3861',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.via.capacity_for_love","max":5,"min":1,"sourceConstruct":"Capacity for love","timeframe":"general-self-description","unit":"points"},"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","variants":[{"template":{"actions":["Для результата {{value}} (1–5) по теме «Способность к близости» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Подумайте об одних безопасных отношениях и удобном способе выразить или принять заботу; близость и прикосновения всегда остаются выбором."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Способность к близости","continuous":true,"currentBand":null,"label":"Описательный результат (1–5)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Способность к близости: {{value}} (1–5). Больший балл описывает большую лёгкость выражения и принятия тёплых чувств и ощущение взаимной заботы; меньший — меньше такого опыта в ответах. Важны безопасность отношений и доступная поддержка; балл не определяет, достойны ли вы любви. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 4 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","summary":"Больший балл описывает большую лёгкость выражения и принятия тёплых чувств и ощущение взаимной заботы; меньший — меньше такого опыта в ответах. Важны безопасность отношений и доступная поддержка; балл не определяет, достойны ли вы любви. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5]}]}],"discoveryClassification":{"basis":"discovery-only-not-clinical-validation","kind":"professional","policySource":"lib/assessments/test-kinds.js","policySourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","policySourceSha256":"sha256:77c573884f78cdc8c4fb58b15990dcce50218c4b6666a89c1ffe2fe8a4142167"},"interpretationVersion":"2026-10-17.v1","provenance":{"assessmentVersionId":"ac69dd83-0fa4-5ffd-ae46-f86e48edd369","contentHash":"sha256:666d2327041