INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT '4599d220-c3c1-5a32-acbb-3fce95d4bb4c'::uuid,'2026-10-17.v1','ru','sha256:8e7c130cd2eebf63ed2f63a1a618649c62023b61295be76928ae6d5fbf329828','{"assessmentVersionId":"4599d220-c3c1-5a32-acbb-3fce95d4bb4c","definitionKey":"ipip-via-r-forgiveness-4","definitionVersion":"v1","instrumentLocale":"en","translationVersion":"original-en-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:8e7c130cd2eebf63ed2f63a1a618649c62023b61295be76928ae6d5fbf329828"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:47ac568effbf07151a459481e6e0950bccebe9ce7953ed0f07c34fe59f19f245',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.via.forgiveness","max":5,"min":1,"sourceConstruct":"Forgiveness / mercy","timeframe":"general-self-description","unit":"points"},"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","variants":[{"template":{"actions":["Для результата {{value}} (1–5) по теме «Прощение и милосердие» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Если это полезно, отделите освобождение от обиды от решения о границах безопасности; возобновлять контакт не обязательно."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Прощение и милосердие","continuous":true,"currentBand":null,"label":"Описательный результат (1–5)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Прощение и милосердие: {{value}} (1–5). Больший балл описывает большую готовность понять чужой проступок и дать новый шанс, с меньшей склонностью хранить обиду; меньший — больше трудностей с этим. Прощение не требует примирения, восстановления доверия или терпимости к вреду. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 4 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","summary":"Больший балл описывает большую готовность понять чужой проступок и дать новый шанс, с меньшей склонностью хранить обиду; меньший — больше трудностей с этим. Прощение не требует примирения, восстановления доверия или терпимости к вреду. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5]}]}],"discoveryClassification":{"basis":"discovery-only-not-clinical-validation","kind":"professional","policySource":"lib/assessments/test-kinds.js","policySourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","policySourceSha256":"sha256:77c573884f78cdc8c4fb58b15990dcce50218c4b6666a89c1ffe2fe8a4142167"},"interpretationVersion":"2026-10-17.v1","provenance":{"assessmentVersionId":"4599d220-c3c1-5a32-acbb-3fce95d4bb4c","contentHash":"sha256:8e7c130cd2eebf63ed2f63a1a618649c62023b61295b