INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT '39bc7056-3b0e-5377-aac8-34f30bb26676'::uuid,'2026-10-17.v1','ru','sha256:7fdef804146664b189154653d856946b7d275b192b4b5832442418c2a41fda9d','{"assessmentVersionId":"39bc7056-3b0e-5377-aac8-34f30bb26676","definitionKey":"ipip-via-r-perseverance-4","definitionVersion":"v1","instrumentLocale":"en","translationVersion":"original-en-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:7fdef804146664b189154653d856946b7d275b192b4b5832442418c2a41fda9d"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:26b2567d4fa4a91f6229f2f81f6b3db04c70ee6bd460511e9c8a5c264f1c48be',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.via.perseverance","max":5,"min":1,"sourceConstruct":"Perseverance","timeframe":"general-self-description","unit":"points"},"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","variants":[{"template":{"actions":["Для результата {{value}} (1–5) по теме «Упорство» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Для одной незавершённой цели решите, сделать ли небольшой следующий шаг, изменить подход или осознанно остановиться."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Упорство","continuous":true,"currentBand":null,"label":"Описательный результат (1–5)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Упорство: {{value}} (1–5). Больший балл описывает продолжение и завершение дел вопреки препятствиям; меньший — больше трудностей с продолжением или завершением. Упорство не всегда полезно, если цель небезопасна, слишком затратна или потеряла смысл. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 4 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","summary":"Больший балл описывает продолжение и завершение дел вопреки препятствиям; меньший — больше трудностей с продолжением или завершением. Упорство не всегда полезно, если цель небезопасна, слишком затратна или потеряла смысл. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5]}]}],"discoveryClassification":{"basis":"discovery-only-not-clinical-validation","kind":"professional","policySource":"lib/assessments/test-kinds.js","policySourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","policySourceSha256":"sha256:77c573884f78cdc8c4fb58b15990dcce50218c4b6666a89c1ffe2fe8a4142167"},"interpretationVersion":"2026-10-17.v1","provenance":{"assessmentVersionId":"39bc7056-3b0e-5377-aac8-34f30bb26676","contentHash":"sha256:7fdef804146664b189154653d856946b7d275b192b4b5832442418c2a41fda9d","definitionKey":"ipip-via-r-perseverance-4","definition