INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT 'c7da129b-23b9-5b9d-a92b-b8b13e6cf482'::uuid,'2026-10-17.v1','ru','sha256:1e54753d89c37efd782cc28eb2b70862c83417daf08d1af419a07a1f007f32ee','{"assessmentVersionId":"c7da129b-23b9-5b9d-a92b-b8b13e6cf482","definitionKey":"ipip-via-r-zest-4","definitionVersion":"v1","instrumentLocale":"en","translationVersion":"original-en-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:1e54753d89c37efd782cc28eb2b70862c83417daf08d1af419a07a1f007f32ee"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:f9f0286e335034740e5b3ab1a0136f7d9d012200bf1c67c4a86131514a2e7e15',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.via.zest","max":5,"min":1,"sourceConstruct":"Vitality / zest","timeframe":"general-self-description","unit":"points"},"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","variants":[{"template":{"actions":["Для результата {{value}} (1–5) по теме «Живость и энтузиазм» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Заметьте, какие занятия восстанавливают или отнимают силы, и оставляйте время на отдых; стойкое необъяснимое истощение стоит обсудить с врачом."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Живость и энтузиазм","continuous":true,"currentBand":null,"label":"Описательный результат (1–5)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Живость и энтузиазм: {{value}} (1–5). Больший балл описывает больше энергии, предвкушения и энтузиазма в повседневной жизни; меньший — меньше такой живости в ответах. На ответы могут влиять сон, здоровье и нагрузка; это не медицинская оценка усталости. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 4 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","summary":"Больший балл описывает больше энергии, предвкушения и энтузиазма в повседневной жизни; меньший — меньше такой живости в ответах. На ответы могут влиять сон, здоровье и нагрузка; это не медицинская оценка усталости. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5]}]}],"discoveryClassification":{"basis":"discovery-only-not-clinical-validation","kind":"professional","policySource":"lib/assessments/test-kinds.js","policySourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","policySourceSha256":"sha256:77c573884f78cdc8c4fb58b15990dcce50218c4b6666a89c1ffe2fe8a4142167"},"interpretationVersion":"2026-10-17.v1","provenance":{"assessmentVersionId":"c7da129b-23b9-5b9d-a92b-b8b13e6cf482","contentHash":"sha256:1e54753d89c37efd782cc28eb2b70862c83417daf08d1af419a07a1f007f32ee","definitionKey":"ipip-