INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT '6fa6fd5a-0e86-5164-a898-3674a54435e1'::uuid,'2026-10-17.v1','ru','sha256:6f06f6388d14f825d708dff59421e36645198ad2aca4f4e53dba9153c39af834','{"assessmentVersionId":"6fa6fd5a-0e86-5164-a898-3674a54435e1","definitionKey":"tipi-10","definitionVersion":"v1","instrumentLocale":"en","translationVersion":"original-en-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:6f06f6388d14f825d708dff59421e36645198ad2aca4f4e53dba9153c39af834"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:96421f0427d370d83f9c63e8da1fe579dfe73355289a6d220a862d2b367c978f',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[1,1.5,2,2.5,3,3.5,4,4.5,5,5.5,6,6.5,7],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.tipi.extraversion","max":7,"min":1,"sourceConstruct":"Extraversion","timeframe":"general-self-description","unit":"points"},"source":"https://gosling.psy.utexas.edu/scales-weve-developed/ten-item-personality-measure-tipi/ten-item-personality-inventory-tipi/","variants":[{"template":{"actions":["Для результата {{value}} (1–7) по теме «Экстраверсия» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Сравните комфорт в оживлённой компании и более спокойном общении и учитывайте это при планировании встреч."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Экстраверсия","continuous":true,"currentBand":null,"label":"Описательный результат (1–7)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Экстраверсия: {{value}} (1–7). Больший балл описывает более общительный, увлечённый стиль; меньший — более сдержанный и спокойный в общении. Эта очень краткая оценка по двум пунктам не показывает всё разнообразие поведения в разных обстоятельствах. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 2 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://gosling.psy.utexas.edu/scales-weve-developed/ten-item-personality-measure-tipi/ten-item-personality-inventory-tipi/","summary":"Больший балл описывает более общительный, увлечённый стиль; меньший — более сдержанный и спокойный в общении. Эта очень краткая оценка по двум пунктам не показывает всё разнообразие поведения в разных обстоятельствах. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.5,2,2.5,3,3.5,4,4.5,5,5.5,6,6.5,7]}]},{"allowedValues":[1,1.5,2,2.5,3,3.5,4,4.5,5,5.5,6,6.5,7],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.tipi.agreeableness","max":7,"min":1,"sourceConstruct":"Agreeableness","timeframe":"general-self-description","unit":"points"},"source":"https://gosling.psy.utexas.edu/scales-weve-developed/ten-item-personality-measure-tipi/ten-item-personality-inventory-tipi/","variants":[{"template":{"actions":["Для результата {{value}} (1–7) по теме «Доброжелательность» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: При разногласии попробуйте ясно выразить свою позицию и проверить, правильно ли поняли точку зрения собеседника."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Доброжелательность","continuous":true,"currentBand":null,"label":"Описательный результат (1–7)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Доброжелательность: {{value}} (1–7). Больший балл описывает больше теплоты и сочувствия и меньше склонности к ссорам; меньший — более критичное или конфликтное самоописание. Два пункта не устанавливают справедливость, надёжность или совместимость в отношениях. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 2 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://gosling.psy.utexas.edu/scales-weve-developed/ten-item-personality-measure-tipi/ten-item-personality-inventory-tipi/","summary":"Больший балл описывает больше теплоты и сочувствия и меньше склонности к ссорам; меньший — более критичное или конфликтное самоописание. Два пункта не устанавливают справедливость, надёжность или совместимость в отношениях. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.5,2,2.5,3,3.5,4,4.5,5,5.5,6,6.5,7]}]},{"allowedValues":[1,1.5,2,2.5,3,3.5,4,4.5,5,5.5,6,6.5,7],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.tipi.conscientiousness","max":7,"min":1,"sourceConstruct":"Conscientiousness","timeframe":"general-self-description","unit":"points"},"source":"https://gosling.psy.utexas.edu/scales-weve-developed/ten-item-personality-measure-tipi/ten-item-personality-inventory-tipi/","variants":[{"template":{"actions":["Для результата {{value}} (1–7) по теме «Организованность» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Выберите одно обязательство, уточните следующий шаг и срок и пересмотрите их, если нагрузка нереалистична."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Организованность","continuous":true,"currentBand":null,"label":"Описательный результат (1–7)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Организованность: {{value}} (1–7). Больший балл описывает больше надёжности, самодисциплины и организованности; меньший — больше неорганизованности или невнимательности в самоописании. Эта широкая оценка по двум пунктам не объясняет, почему было трудно выполнить конкретное обязательство. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 2 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://gosling.psy.utexas.edu/scales-weve-developed/ten-item-personality-measure-tipi/ten-item-personality-inventory-tipi/","summary":"Больший балл описывает больше надёжности, самодисциплины и организованности; меньший — больше неорганизованности или невнимательности в самоописании. Эта широкая оценка по двум пунктам не объясняет, почему было трудно выполнить конкретное обязательство. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.5,2,2.5,3,3.5,4,4.5,5,5.5,6,6.5,7]}]},{"allowedValues":[1,1.5,2,2.5,3,3.5,4,4.5,5,5.5,6,6.5,7],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.tipi.emotional_stability","max":7,"min":1,"sourceConstruct":"Emotional stability","timeframe":"general-self-description","unit":"points"},"source":"https://gosling.psy.utexas.edu/scales-weve-developed/ten-item-personality-measure-tipi/ten-item-personality-inventory-tipi/","variants":[{"template":{"actions":["Для результата {{value}} (1–7) по теме «Эмоциональная устойчивость» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Вспомните напряжённый момент и отметьте, что поддержало спокойствие или какой поддержки не хватило, без требования всегда быть невозмутимым."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Эмоциональная устойчивость","continuous":true,"currentBand":null,"label":"Описательный результат (1–7)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Эмоциональная устойчивость: {{value}} (1–7). Больший балл описывает больше спокойствия и эмоциональной устойчивости; меньший — больше тревоги и лёгкости возникновения огорчения. Направление противоположно баллу нейротизма. Два пункта не диагностируют тревожное расстройство и не оценивают совладание во всех ситуациях. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 2 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://gosling.psy.utexas.edu/scales-weve-developed/ten-item-personality-measure-tipi/ten-item-personality-inventory-tipi/","summary":"Больший балл описывает больше спокойствия и эмоциональной устойчивости; меньший — больше тревоги и лёгкости возникновения огорчения. Направление противоположно баллу нейротизма. Два пункта не диагностируют тревожное расстройство и не оценивают совладание во всех ситуациях. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.5,2,2.5,3,3.5,4,4.5,5,5.5,6,6.5,7]}]},{"allowedValues":[1,1.5,2,2.5,3,3.5,4,4.5,5,5.5,6,6.5,7],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.tipi.openness","max":7,"min":1,"sourceConstruct":"Openness to experience","timeframe":"general-self-description","unit":"points"},"source":"https://gosling.psy.utexas.edu/scales-weve-developed/ten-item-personality-measure-tipi/ten-item-personality-inventory-tipi/","variants":[{"template":{"actions":["Для результата {{value}} (1–7) по теме «Открытость опыту» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Если хочется разнообразия, попробуйте небольшой новый опыт, от которого легко отказаться; сохранить привычное предпочтение тоже допустимо."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Открытость опыту","continuous":true,"currentBand":null,"label":"Описательный результат (1–7)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Открытость опыту: {{value}} (1–7). Больший балл описывает большую открытость незнакомому опыту и менее традиционное самоописание; меньший — более привычные, традиционные предпочтения. Оценка по двум пунктам не является тестом интеллекта или рейтингом образа жизни. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 2 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://gosling.psy.utexas.edu/scales-weve-developed/ten-item-personality-measure-tipi/ten-item-personality-inventory-tipi/","summary":"Больший балл описывает большую открытость незнакомому опыту и менее традиционное самоописание; меньший — более привычные, традиционные предпочтения. Оценка по двум пунктам не является тестом интеллекта или рейтингом образа жизни. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.5,2,2.5,3,3.5,4,4.5,5,5.5,6,6.5,7]}]}],"discoveryClassification":{"basis":"discovery-only-not-clinical-validation","kind":"professional","policySource":"lib/assessments/test-kinds.js","policySourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","policySourceSha256":"sha256:77c573884f78cdc8c4fb58b15990dcce50218c4b6666a89c1ffe2fe8a4142167"},"interpretationVersion":"2026-10-17.v1","provenance":{"assessmentVersionId":"6fa6fd5a-0e86-5164-a898-3674a54435e1","contentHash":"sha256:6f06f6388d14f825d708dff59421e36645198ad2aca4f4e53dba9153c39af834","definitionKey":"tipi-10","definitionVersion":"v1","instrumentLocale":"en","resultVersion":"v1","scoringKey":"configured","scoringVersion":"v1","translationVersion":"original-en-v1"},"rendererStrategy":"finite-domain-template.v1","reportLocale":"ru","rulesEngineVersion":"2026-10-16.v10","schemaVersion":"hh-interpretation.v1","source":{"citation":"Gosling, S. D., Rentfrow, P. J., & Swann, W. B. Jr. (2003). A very brief measure of the Big-Five personality domains. Journal of Research in Personality, 37, 504–528.","interpretation":"Ten very brief English items produce five 1–7 mean trait scores, not clinical norms or conditions.","permission":"Author explicitly permits reproduction for any purpose without asking permission.","permissionUrl":"https://gosling.psy.utexas.edu/scales-weve-developed/ten-item-personality-measure-tipi/","reviewedAt":"2026-10-11","scoringUrl":"https://gosling.psy.utexas.edu/scales-weve-developed/ten-item-personality-measure-tipi/ten-item-personality-inventory-tipi/","title":"Ten-Item Personality Inventory (TIPI)","url":"https://gosling.psy.utexas.edu/scales-weve-developed/ten-item-personality-measure-tipi/ten-item-personality-inventory-tipi/"},"sourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","s