INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT '4282c169-808a-5a23-9c3e-bac9d2696a8d'::uuid,'2026-10-17.v1','ru','sha256:803f2b30412509f8a40861ce8cb34adb04285a78c17668f1438902e84cd4bb31','{"assessmentVersionId":"4282c169-808a-5a23-9c3e-bac9d2696a8d","definitionKey":"ipip-via-r-appreciation-beauty-4","definitionVersion":"v1","instrumentLocale":"en","translationVersion":"original-en-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:803f2b30412509f8a40861ce8cb34adb04285a78c17668f1438902e84cd4bb31"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:62758225e03f945676404cf170fcf56e7fb797b28e50fb5d17aa0d235361339f',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.via.appreciation_beauty","max":5,"min":1,"sourceConstruct":"Appreciation of beauty","timeframe":"general-self-description","unit":"points"},"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","variants":[{"template":{"actions":["Для результата {{value}} (1–5) по теме «Восприятие красоты» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Если это доступно и приятно, ненадолго остановитесь у понравившегося вида, звука или предмета и заметьте свой отклик."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Восприятие красоты","continuous":true,"currentBand":null,"label":"Описательный результат (1–5)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Восприятие красоты: {{value}} (1–5). Больший балл описывает больше внимания и эмоционального отклика на красоту, в том числе в природе; меньший — меньше такого внимания в ответах. Это не проверка художественного вкуса или обязанность любить искусство. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 4 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","summary":"Больший балл описывает больше внимания и эмоционального отклика на красоту, в том числе в природе; меньший — меньше такого внимания в ответах. Это не проверка художественного вкуса или обязанность любить искусство. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5]}]}],"discoveryClassification":{"basis":"discovery-only-not-clinical-validation","kind":"professional","policySource":"lib/assessments/test-kinds.js","policySourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","policySourceSha256":"sha256:77c573884f78cdc8c4fb58b15990dcce50218c4b6666a89c1ffe2fe8a4142167"},"interpretationVersion":"2026-10-17.v1","provenance":{"assessmentVersionId":"4282c169-808a-5a23-9c3e-bac9d2696a8d","contentHash":"sha256:803f2b30412509f8a40861ce8cb34adb04285a78c17668f1438902e84cd4bb31","definitionKey