INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT 'c239828d-da4c-5de2-9e50-aa38fad4ad32'::uuid,'2026-10-17.v1','ru','sha256:bc7261e9a3b92dcb97e1d89384f5246f1b692cf426dacaf6250bee772da4620b','{"assessmentVersionId":"c239828d-da4c-5de2-9e50-aa38fad4ad32","definitionKey":"ipip-via-r-bravery-4","definitionVersion":"v1","instrumentLocale":"en","translationVersion":"original-en-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:bc7261e9a3b92dcb97e1d89384f5246f1b692cf426dacaf6250bee772da4620b"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:2a3438e08e52324194a94e272bad45e0d34c56dad2cfb5f7d770af879044e5d1',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.via.bravery","max":5,"min":1,"sourceConstruct":"Bravery and courage","timeframe":"general-self-description","unit":"points"},"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","variants":[{"template":{"actions":["Для результата {{value}} (1–5) по теме «Смелость в выражении позиции» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Если важно высказаться, оцените риски и выберите безопасный канал или союзника; молчание может быть защитным выбором."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Смелость в выражении позиции","continuous":true,"currentBand":null,"label":"Описательный результат (1–5)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Смелость в выражении позиции: {{value}} (1–5). Больший балл описывает большую готовность выражать убеждения и непопулярные мнения вопреки сопротивлению; меньший — большую сдержанность при возможных последствиях. Пункты касаются высказывания позиции, а не всех форм смелости или готовности к физической опасности. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 4 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","summary":"Больший балл описывает большую готовность выражать убеждения и непопулярные мнения вопреки сопротивлению; меньший — большую сдержанность при возможных последствиях. Пункты касаются высказывания позиции, а не всех форм смелости или готовности к физической опасности. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5]}]}],"discoveryClassification":{"basis":"discovery-only-not-clinical-validation","kind":"professional","policySource":"lib/assessments/test-kinds.js","policySourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","policySourceSha256":"sha256:77c573884f78cdc8c4fb58b15990dcce50218c4b6666a89c1ffe2fe8a4142167"},"interpretationVersion":"2026-10-17.v1","provenance":{"assessmentVersionId":"c239828d-da4c-5de2-9e50-aa38fad4ad3