INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT '24df183a-da18-5e99-bba8-d4f1210e7964'::uuid,'2026-10-17.v1','ru','sha256:ac178dac957f016420a331771e082346c2b65130d9e50b58edbdfa520cff727d','{"assessmentVersionId":"24df183a-da18-5e99-bba8-d4f1210e7964","definitionKey":"ipip-via-r-core-positivity-6","definitionVersion":"v1","instrumentLocale":"en","translationVersion":"original-en-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:ac178dac957f016420a331771e082346c2b65130d9e50b58edbdfa520cff727d"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:295d5a1ef3a8e6aa6e42a57e52b709e471e569a887524beb7f8cd7cdb8f293a9',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[1,1.17,1.33,1.5,1.67,1.83,2,2.17,2.33,2.5,2.67,2.83,3,3.17,3.33,3.5,3.67,3.83,4,4.17,4.33,4.5,4.67,4.83,5],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.via.core.positivity","max":5,"min":1,"sourceConstruct":"Global core strength: positivity","timeframe":"general-self-description","unit":"points"},"source":"https://ipip.ori.org/IPIP-VIA-R-core-strengths_Key.html","variants":[{"template":{"actions":["Для результата {{value}} (1–5) по теме «Обобщённая сила: позитивность» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Заметьте, какая часть сочетания вам доступна, а какая нет; выберите реалистичный источник поддержки без требования позитивности или прощения."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Обобщённая сила: позитивность","continuous":true,"currentBand":null,"label":"Описательный результат (1–5)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Обобщённая сила: позитивность: {{value}} (1–5). Больший балл описывает сочетание надежды, энтузиазма, взаимной заботы, благодарности, прощения и принятия любви; меньший — меньшее согласие с этим сочетанием. Разные ответы могут дать одинаковое среднее; это не общий балл счастья или психического здоровья. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 6 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://ipip.ori.org/IPIP-VIA-R-core-strengths_Key.html","summary":"Больший балл описывает сочетание надежды, энтузиазма, взаимной заботы, благодарности, прощения и принятия любви; меньший — меньшее согласие с этим сочетанием. Разные ответы могут дать одинаковое среднее; это не общий балл счастья или психического здоровья. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.17,1.33,1.5,1.67,1.83,2,2.17,2.33,2.5,2.67,2.83,3,3.17,3.33,3.5,3.67,3.83,4,4.17,4.33,4.5,4.67,4.83,5]}]}],"discoveryClassification":{"basis":"discovery-only-not-clinical-validation","kind":"professional","policySource":"lib/assessments/test-kinds.js","policySourceCommit":"d9ba8b92eb7bff99864d5403d9a78a199b727892","policySourceSha256":"sha256:77c573884f78cdc8c4fb58b15990dcc