INSERT INTO app.assessment_interpretation_versions (assessment_version_id,interpretation_version,report_locale,definition_content_hash,provenance,source_commit,rules_engine_version,payload_sha256,payload_canonical,payload) SELECT 'a72fd3a8-343c-5499-a9af-3ab45f1633e6'::uuid,'2026-10-17.v1','ru','sha256:34ea675fe4539c8052bc80c8ec65e65669b98693ec2c450ab70e7c4611d3c37e','{"assessmentVersionId":"a72fd3a8-343c-5499-a9af-3ab45f1633e6","definitionKey":"ipip-via-r-strengths-96","definitionVersion":"v1","instrumentLocale":"en","translationVersion":"original-en-v1","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","contentHash":"sha256:34ea675fe4539c8052bc80c8ec65e65669b98693ec2c450ab70e7c4611d3c37e"}'::jsonb,'d9ba8b92eb7bff99864d5403d9a78a199b727892','2026-10-16.v10','sha256:46916e6c5bfa3f2b6c8135d05ff297fbc4b6fc38ab76cc45dc9a1d7eeea91eb8',v.payload_canonical,v.payload_canonical::jsonb FROM (VALUES ('{"catalogActive":true,"dimensions":[{"allowedValues":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.via.appreciation_beauty","max":5,"min":1,"sourceConstruct":"Appreciation of beauty","timeframe":"general-self-description","unit":"points"},"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","variants":[{"template":{"actions":["Для результата {{value}} (1–5) по теме «Восприятие красоты» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Если это доступно и приятно, ненадолго остановитесь у понравившегося вида, звука или предмета и заметьте свой отклик."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Восприятие красоты","continuous":true,"currentBand":null,"label":"Описательный результат (1–5)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Восприятие красоты: {{value}} (1–5). Больший балл описывает больше внимания и эмоционального отклика на красоту, в том числе в природе; меньший — меньше такого внимания в ответах. Это не проверка художественного вкуса или обязанность любить искусство. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 4 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","summary":"Больший балл описывает больше внимания и эмоционального отклика на красоту, в том числе в природе; меньший — меньше такого внимания в ответах. Это не проверка художественного вкуса или обязанность любить искусство. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5]}]},{"allowedValues":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.via.bravery","max":5,"min":1,"sourceConstruct":"Bravery and courage","timeframe":"general-self-description","unit":"points"},"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","variants":[{"template":{"actions":["Для результата {{value}} (1–5) по теме «Смелость в выражении позиции» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Если важно высказаться, оцените риски и выберите безопасный канал или союзника; молчание может быть защитным выбором."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Смелость в выражении позиции","continuous":true,"currentBand":null,"label":"Описательный результат (1–5)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Смелость в выражении позиции: {{value}} (1–5). Больший балл описывает большую готовность выражать убеждения и непопулярные мнения вопреки сопротивлению; меньший — большую сдержанность при возможных последствиях. Пункты касаются высказывания позиции, а не всех форм смелости или готовности к физической опасности. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 4 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.","presentationDirection":"neutral","recommendedReview":false,"reliableDirection":true,"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","summary":"Больший балл описывает большую готовность выражать убеждения и непопулярные мнения вопреки сопротивлению; меньший — большую сдержанность при возможных последствиях. Пункты касаются высказывания позиции, а не всех форм смелости или готовности к физической опасности. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль.","verified":true},"values":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5]}]},{"allowedValues":[1,1.25,1.5,1.75,2,2.25,2.5,2.75,3,3.25,3.5,3.75,4,4.25,4.5,4.75,5],"mode":"descriptive","signature":{"dimensionClass":"trait","direction":"non-normative","key":"trait.via.capacity_for_love","max":5,"min":1,"sourceConstruct":"Capacity for love","timeframe":"general-self-description","unit":"points"},"source":"https://ipip.ori.org/IPIP-VIA-R_Key.html","variants":[{"template":{"actions":["Для результата {{value}} (1–5) по теме «Способность к близости» запишите ситуацию, где это описание подходит, и исключение. Сравнивайте гибкость поведения, не стремясь к «правильному» баллу.","По желанию: Подумайте об одних безопасных отношениях и удобном способе выразить или принять заботу; близость и прикосновения всегда остаются выбором."],"bands":[],"basis":"descriptive","code":"continuous","construct":"Способность к близости","continuous":true,"currentBand":null,"label":"Описательный результат (1–5)","limitations":["Для этой версии здесь не применяются проверенные категориальные пороги. Балл не является диагнозом, нормой или процентилем.","Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника."],"meaning":"Способность к близости: {{value}} (1–5). Больший балл описывает большую лёгкость выражения и принятия тёплых чувств и ощущение взаимной заботы; меньший — меньше такого опыта в ответах. Важны безопасность отношений и доступная поддержка; балл не определяет, достойны ли вы любви. Это непрерывное самоописание с авторским пояснением Holistic House, а не валидированная интерпретационная категория; границы шкалы показывают возможные баллы, а не норму или процентиль. Среднее 4 ответов после обратного кодирования указанных в ключе пунктов. Проверенные клинические категории для этого результата здесь не присваиваются. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника.